import { NextRequest, NextResponse } from "next/server";
import { jwtVerify, importJWK, JWTPayload } from "jose";
import { attachCsrfCookie } from "@/lib/csrf";
import { logSecurityEvent } from "@/lib/security-logger";

const SESSION_COOKIE_NAME = "__session";
const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 5; // 5 days

// EC public key from local Supabase GoTrue config (GOTRUE_JWT_KEYS)
// This is the public half of the ES256 signing key pair auto-generated by `supabase start`
const EC_PUBLIC_JWK = {
  kty: "EC",
  use: "sig",
  crv: "P-256",
  x: "M5Sjqn5zwC9Kl1zVfUUGvv9boQjCGd45G8sdopBExB4",
  y: "P6IXMvA2WYXSHSOMTBH2jsw_9rrzGy89FjPf6oOsIxQ",
};

function decodeJwtHeader(token: string): { alg?: string } {
  try {
    const headerB64 = token.split(".")[0];
    const padded = headerB64.replace(/-/g, "+").replace(/_/g, "/");
    const json = Buffer.from(padded, "base64").toString("utf-8");
    return JSON.parse(json);
  } catch {
    return {};
  }
}

async function verifyToken(token: string): Promise<JWTPayload> {
  const header = decodeJwtHeader(token);

  if (header.alg === "ES256") {
    // Local Supabase v2+ signs with EC P-256 (ES256)
    const key = await importJWK(EC_PUBLIC_JWK, "ES256");
    const { payload } = await jwtVerify(token, key, {
      audience: "authenticated",
      algorithms: ["ES256"],
    });
    return payload;
  }

  // Fallback: HMAC-SHA256 (HS256) — cloud and older local setups
  const secret = new TextEncoder().encode(process.env.SUPABASE_JWT_SECRET);
  const { payload } = await jwtVerify(token, secret, {
    audience: "authenticated",
    algorithms: ["HS256"],
  });
  return payload;
}

export async function POST(req: NextRequest) {
  let body: Record<string, unknown> = {};
  try {
    body = await req.json();
  } catch {
    // treat as empty body
  }

  const { accessToken, action } = body as { accessToken?: string; action?: string };
  const ip =
    req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ?? "unknown";
  const isHttps = req.nextUrl.protocol === "https:";

  const cookieBase = {
    httpOnly: true,
    secure: isHttps,
    sameSite: "strict" as const,
    path: "/",
  };

  // ── CLEAR ────────────────────────────────────────────────────────────────
  if (action === "clear" || !accessToken) {
    const res = NextResponse.json({ ok: true });
    res.cookies.set({ name: SESSION_COOKIE_NAME, value: "", ...cookieBase, maxAge: 0 });
    res.cookies.set({
      name: "__csrf",
      value: "",
      httpOnly: false,
      secure: isHttps,
      sameSite: "strict" as const,
      path: "/",
      maxAge: 0,
    });
    logSecurityEvent({ type: "LOGOUT", severity: "INFO", ip, details: "Session cleared" });
    return res;
  }

  // ── BASIC VALIDATION ──────────────────────────────────────────────────────
  if (typeof accessToken !== "string" || accessToken.length < 20) {
    return NextResponse.json({ ok: false, error: "Invalid token format" }, { status: 400 });
  }

  // ── VERIFY TOKEN LOCALLY ──────────────────────────────────────────────────
  try {
    const payload = await verifyToken(accessToken);

    const res = NextResponse.json({ ok: true });
    res.cookies.set({
      name: SESSION_COOKIE_NAME,
      value: accessToken,
      ...cookieBase,
      maxAge: SESSION_MAX_AGE_SECONDS,
    });
    attachCsrfCookie(res, isHttps);

    logSecurityEvent({
      type: "LOGIN_SUCCESS",
      severity: "INFO",
      userId: payload.sub as string,
      ip,
      details: "Session cookie minted",
    });
    return res;
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("[Session] Token verification failed:", message);
    logSecurityEvent({
      type: "TOKEN_VERIFY_FAIL",
      severity: "WARNING",
      ip,
      details: `Verification failed: ${message.substring(0, 200)}`,
    });
    return NextResponse.json({ ok: false, error: "Invalid or revoked token" }, { status: 401 });
  }
}
